import 'package:sehatak/core/models/pregnancy/pregnancy_models.dart';
class PregnancyState{final bool isLoading;final List<PregnancyDoctor> doctors;final List<PregnancyClinic> clinics;final List<PregnancyTip> tips;final List<PregnancyHospital> hospitals;final PregnancyTracker? tracker;final String? selectedSpecialty,errorMessage;const PregnancyState({this.isLoading=false,this.doctors=const[],this.clinics=const[],this.tips=const[],this.hospitals=const[],this.tracker,this.selectedSpecialty,this.errorMessage});PregnancyState copyWith({bool?isLoading,List<PregnancyDoctor>?doctors,List<PregnancyClinic>?clinics,List<PregnancyTip>?tips,List<PregnancyHospital>?hospitals,PregnancyTracker?tracker,String?selectedSpecialty,String?errorMessage})=>PregnancyState(isLoading:isLoading??this.isLoading,doctors:doctors??this.doctors,clinics:clinics??this.clinics,tips:tips??this.tips,hospitals:hospitals??this.hospitals,tracker:tracker??this.tracker,selectedSpecialty:selectedSpecialty??this.selectedSpecialty,errorMessage:errorMessage);}
